<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
const props=defineProps({values:{type:Array,default:()=>[]},times:{type:Array,default:()=>[]},series:{type:Array,default:()=>[]},spark:Boolean,plotHeight:Number,label:{type:String,default:'处理器平均温度'},unit:{type:String,default:''},minimum:Number,maximum:Number,legend:Boolean});
const colors=['#52d4d5','#13a38a','#9b70ed'];
const plot=ref(null),width=ref(400),renderedHeight=ref(0),preferredHeight=computed(()=>props.plotHeight||(props.spark?106:145)),height=computed(()=>renderedHeight.value||preferredHeight.value);let observer;
onMounted(()=>{observer=new ResizeObserver(entries=>{const size=entries[0].contentRect;width.value=Math.max(1,size.width);renderedHeight.value=Math.max(1,size.height);});if(plot.value)observer.observe(plot.value);});onBeforeUnmount(()=>observer?.disconnect());
const lines=computed(()=>(props.series.length?props.series:[{name:props.label,values:props.values}]).map((s,i)=>({...s,color:s.color||colors[i%3],values:(s.values||[]).map(v=>v==null||v===''?null:Number.isFinite(Number(v))?Number(v):null)})));
const bounds=computed(()=>{const values=lines.value.flatMap(s=>s.values).filter(v=>v!=null),lo=values.length?Math.min(...values):0,hi=values.length?Math.max(...values):1;const margin=Math.max((hi-lo)*.18,props.unit==='GHz'?.1:1);return{min:props.minimum??Math.max(0,Math.floor((lo-margin)*10)/10),max:props.maximum??Math.ceil((hi+margin)*10)/10};});
const left=computed(()=>Math.max(42,...ticks.value.map(t=>String(tick(t.value)).length*7+16))),top=24,right=computed(()=>width.value-14),bottom=computed(()=>height.value-28);
const coords=values=>values.map((v,i)=>v==null?null:[left.value+(right.value-left.value)*i/Math.max(1,values.length-1),bottom.value-(bottom.value-top)*(v-bounds.value.min)/Math.max(.1,bounds.value.max-bounds.value.min)]);
const plots=computed(()=>lines.value.map(s=>{const points=coords(s.values);return{...s,points,path:points.map((p,i)=>p?(i&&points[i-1]?'L':'M')+p.join(' '):'').join(' ')};}));
const ticks=computed(()=>[0,1,2].map(i=>({y:top+(bottom.value-top)*i/2,value:bounds.value.max-(bounds.value.max-bounds.value.min)*i/2})));
const tick=v=>Math.abs(v)>=100?Math.round(v):Number(v.toFixed(props.unit==='GHz'?1:Math.abs(v)<10?1:0));
function timeLabel(f){const value=props.times[Math.round((props.times.length-1)*f)];return value?new Date(value).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):f===0?'较早':f===1?'现在':'';}
</script>
<template><div class="trend-plot" :class="{compact:spark}"><div v-if="legend" class="chart-legend"><span v-for="s in lines" :key="s.name"><i :style="{background:s.color}"></i>{{s.name}}<small v-if="unit">{{unit}}</small></span></div><svg ref="plot" :class="spark?'spark':'chart'" :viewBox="`0 0 ${width} ${height}`" :style="{height:preferredHeight+'px'}" role="img" :aria-label="label+(unit?'，单位'+unit:'')"><g v-for="t in ticks" :key="t.y"><line :x1="left" :x2="right" :y1="t.y" :y2="t.y" class="gridline"/><text :x="left-8" :y="t.y+3" text-anchor="end">{{tick(t.value)}}</text></g><text x="4" y="12">{{unit}}</text><template v-for="p in plots" :key="p.name"><path :d="p.path" fill="none" :stroke="p.color" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/><circle v-for="(point,index) in p.points" :key="index" v-show="point&&(p.points.filter(Boolean).length===1||index===p.points.length-1)" :cx="point?.[0]||0" :cy="point?.[1]||0" r="2.5" :fill="p.color"><title>{{p.name}}：{{p.values[index]}} {{unit}}</title></circle></template><text v-if="!plots.some(p=>p.points.some(Boolean))" :x="width/2" :y="height/2" text-anchor="middle">—</text><text v-for="f in [0,.5,1]" :key="f" :x="left+(right-left)*f" :y="height-6" :text-anchor="f===0?'start':f===1?'end':'middle'">{{timeLabel(f)}}</text></svg></div></template>
